parameters.blocksUi:
={
  "blocks": [
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "🧠 *New Comment Suggestions For Approval!*"
      }
    },

    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Post:* <{{ $json.results[0].post_url }}|click here to read the post>"
      }
    },

    { "type": "divider" },

    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*💬 Select ONE comment:*"
      }
    },

    {
      "type": "actions",
      "block_id": "wTF4f",
      "elements": [
        {
          "type": "radio_buttons",
          "action_id": "comment_choice",
          "options": [
            {
              "text": {
                "type": "plain_text",
                "text": "{{ $json.results[0].comment_options[0] }}",
                "emoji": true
              },
              "value": "1"
            },
            {
              "text": {
                "type": "plain_text",
                "text": "{{ $json.results[0].comment_options[1] }}",
                "emoji": true
              },
              "value": "2"
            },
            {
              "text": {
                "type": "plain_text",
                "text": "{{ $json.results[0].comment_options[2] }}",
                "emoji": true
              },
              "value": "3"
            }
          ]
        }
      ]
    },

    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*🔥 Select ONE reaction:*"
      }
    },

    {
      "type": "actions",
      "block_id": "ELF6X",
      "elements": [
        {
          "type": "radio_buttons",
          "action_id": "reaction_choice",
          "options": [
            {
              "text": {
                "type": "plain_text",
                "text": "{{ $json.results[0].reactions[0].emoji }}",
                "emoji": true
              },
              "value": "{{ $json.results[0].reactions[0].code }}"
            },
            {
              "text": {
                "type": "plain_text",
                "text": "{{ $json.results[0].reactions[1].emoji }}",
                "emoji": true
              },
              "value": "{{ $json.results[0].reactions[1].code }}"
            }
          ]
        }
      ]
    },

    { "type": "divider" },

    {
      "type": "actions",
      "elements": [
        {
          "type": "button",
          "action_id": "approve_button",
          "text": {
            "type": "plain_text",
            "text": "Approve",
            "emoji": true
          },
          "value": "{{ 'approve_' + $json.results[0].post_id }}"
        },
        {
          "type": "button",
          "action_id": "decline_button",
          "text": {
            "type": "plain_text",
            "text": "Decline",
            "emoji": true
          },
          "value": "{{ 'decline_' + $json.results[0].post_id }}"
        }
      ]
    }
  ]
}
